function isFFDomain(url){
  try{if(!url) return false;var u=String(url).toLowerCase();return u.indexOf('freefiremobile.com')!==-1||u.indexOf('ff.garena.com')!==-1||u.indexOf('garenanow.com')!==-1}catch(e){return false}
}

function overrideHeaders(h, ov){
  var out=Object.assign({}, h||{}); for(var k in ov) out[k]=ov[k]; return out
}

function safeParse(s){
  try{return JSON.parse(s)}catch(e){return null}
}

function safeStringify(o){
  try{return JSON.stringify(o)}catch(e){return ''}
}

function reducePayload(obj){
  if(!obj||typeof obj!=='object') return obj
  var toRemove=['large_images','debug_info','profiling','trace','logs','extra_payload']; for(var i=0;i<toRemove.length;i++){ if(obj.hasOwnProperty(toRemove[i])) delete obj[toRemove[i]] } return obj
}

function floatToFx32BigInt(f){
  if(!isFinite(f)) return 0n
  const sign = f < 0 ? -1n : 1n
  const abs = Math.abs(f)
  const v = BigInt(Math.round(abs * Math.pow(2,32)))
  return sign * v
}

function fx32BigIntToFloat(b){
  if(typeof b !== 'bigint') b = BigInt(b||0)
  const neg = b < 0n
  const abs = neg ? -b : b
  const f = Number(abs) / Math.pow(2,32)
  return neg ? -f : f
}

function fx32ToHex(b){
  if(typeof b !== 'bigint') b = BigInt(b||0)
  const neg = b < 0n
  const abs = neg ? -b : b
  const hex = '0x' + abs.toString(16).padStart(8,'0')
  return neg ? '-' + hex : hex
}

function hexToFx32BigInt(hexStr){
  if(!hexStr && hexStr !== 0) return 0n
  let s = String(hexStr).trim()
  let neg = false
  if(s.startsWith('-')){ neg = true; s = s.slice(1) }
  if(s.startsWith('0x')||s.startsWith('0X')) s = s.slice(2)
  if(s.length===0) return 0n
  const v = BigInt('0x'+s)
  return neg ? -v : v
}

function packFx32XYToHex(xFx32, yFx32){
  const x = (typeof xFx32 === 'bigint') ? xFx32 : BigInt(xFx32||0)
  const y = (typeof yFx32 === 'bigint') ? yFx32 : BigInt(yFx32||0)
  function toU32(n){ let v = BigInt(n); if(v < 0n) v = ((1n<<32n)+v) & ((1n<<32n)-1n); return v & ((1n<<32n)-1n) }
  const ux = toU32(x)
  const uy = toU32(y)
  const packed = (ux << 32n) | uy
  return '0x' + packed.toString(16).padStart(16,'0')
}

function unpackFx32XYFromHex(packedHex){
  let s = String(packedHex).trim()
  if(s.startsWith('0x')||s.startsWith('0X')) s = s.slice(2)
  if(s.length===0) return { xFx32:0n, yFx32:0n }
  const v = BigInt('0x'+s)
  const mask = (1n<<32n)-1n
  let uy = v & mask
  let ux = (v >> 32n) & mask
  function signed32(u){ if(u & (1n<<31n)) return u - (1n<<32n); return u }
  return { xFx32: signed32(ux), yFx32: signed32(uy) }
}

function floatXYToPackedHex(x, y){
  const X = floatToFx32BigInt(x)
  const Y = floatToFx32BigInt(y)
  return packFx32XYToHex(X,Y)
}

function packedHexToFloatXY(packedHex){
  const u = unpackFx32XYFromHex(packedHex)
  return { x: fx32BigIntToFloat(u.xFx32), y: fx32BigIntToFloat(u.yFx32) }
}

function fx32ToBytesLE(xFx32){
  let v = (typeof xFx32==='bigint')? xFx32 : BigInt(xFx32||0)
  if(v < 0n) v = ((1n<<32n) + v) & ((1n<<32n)-1n)
  const b = []
  for(let i=0;i<4;i++){ b.push(Number((v >> (8n*BigInt(i))) & 0xFFn)) }
  return b
}

function bytesLEToFx32(bytes){
  let v = 0n
  for(let i=0;i<bytes.length && i<4;i++){ v |= (BigInt(bytes[i] & 0xFF) << (8n*BigInt(i))) }
  if(v & (1n<<31n)) v = v - (1n<<32n)
  return v
}

function searchNumber(arr, num){
  if(!arr||!arr.length) return -1
  for(var i=0;i<arr.length;i++){ if(arr[i]===num) return i }
  return -1
}

function setValue(obj, key, val){
  if(!obj||typeof obj!=='object') obj={}
  obj[key]=val
  return obj
}

function getValue(obj, key){
  if(!obj||typeof obj!=='object') return undefined
  return obj[key]
}

function removeValue(obj, key){
  if(!obj||typeof obj!=='object') return obj
  delete obj[key]
  return obj
}

function updateValue(obj, key, val){
  if(!obj||typeof obj!=='object') obj={}
  if(obj.hasOwnProperty(key)) obj[key]=val
  return obj
}

