function kalmanCreate(q, r, initialX, initialP){
  return {q:q||1e-5, r:r||1e-2, x:(initialX||0), p:(initialP||1)}
}

function kalmanUpdate(kf, measurement){
  if(!kf) return null
  kf.p = kf.p + kf.q
  var k = kf.p / (kf.p + kf.r)
  kf.x = kf.x + k * (measurement - kf.x)
  kf.p = (1 - k) * kf.p
  return kf.x
}

