function fnzssmjdxmufxy(p1,p2){return {x:p1.x-p2.x,y:p1.y-p2.y};}
function fnjmcvrgiaigxy(a,b){return Math.sqrt(a*a+b*b);}
function fnurhkdlsjtdyr(x,y){return Math.atan2(y,x);}
function fnwqrwffmwrzfx(aim,target,smooth){return {x:aim.x+(target.x-aim.x)/smooth,y:aim.y+(target.y-aim.y)/smooth};}
function fnyrarnxzddypb(min,max){return Math.random()*(max-min)+min;}
function fnvrywblyaylva(recoil){return {x:-recoil.x,y:-recoil.y};}
